package ai.ophone.bridge;

import android.content.Context;
import ai.ophone.workbench.RootJobScript;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.TimeUnit;

/** Real ordinary-UID watchdog fixtures; never present them as successful device root authorization. */
final class NativeRootChecks {
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    static JSONObject a(String... pairs)throws Exception{JSONObject a=new JSONObject();for(int i=0;i<pairs.length;i+=2)a.put(pairs[i],pairs[i+1]);return a;}
    static String read(File file)throws Exception{try(FileInputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
    static void write(File file,String text)throws Exception{file.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(file)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}}
    static final class Fixture implements AutoCloseable {
        final Context c;final File root,lease,identity,exit,reason;Process process;
        Fixture(Context base,String tag)throws Exception {root=new File(base.getCacheDir(),"root-check-"+tag+"-"+UUID.randomUUID());root.mkdirs();c=new android.content.ContextWrapper(base){@Override public File getFilesDir(){return root;}};RootAccess.setEnabled(c,true);lease=new File(root,"lease");identity=new File(root,"identity");exit=new File(root,"exit");reason=new File(root,"reason");write(lease,"1");}
        void start(String command,int requiredUid,long deadline)throws Exception{String script=RootJobScript.script(command,RootAccess.policyFile(c),RootAccess.policy(c).getString("generation"),lease,identity,exit,reason,root,deadline,requiredUid);process=new ProcessBuilder("/system/bin/sh","-c",script).start();}
        void identity()throws Exception {long end=System.currentTimeMillis()+3000;while(!identity.exists()&&System.currentTimeMillis()<end)Thread.sleep(10);check(identity.exists(),"supervisor fixture missing identity");}
        void finished()throws Exception{check(process.waitFor(5000,TimeUnit.MILLISECONDS),"supervisor did not exit");}
        public void close()throws Exception{lease.delete();if(process!=null&&!process.waitFor(1000,TimeUnit.MILLISECONDS))process.destroy();remove(root);}
        static void remove(File f){File[] files=f.listFiles();if(files!=null)for(File child:files)remove(child);f.delete();}
    }
    static JSONArray run(Context c,String suite)throws Exception {
        JSONArray reports=new JSONArray();
        try(Fixture f=new Fixture(c,"disabled")){RootAccess.setEnabled(f.c,false);JSONObject status=RootAccess.probe(f.c);check(!status.optBoolean("enabled")&&!status.optBoolean("available")&&status.optString("error").equals("root_shell_disabled_by_user"),"disabled probe requested root");reports.put("root_off_probe_does_not_authorize");}
        try(Fixture f=new Fixture(c,"generation")){String generation=RootAccess.policy(f.c).getString("generation");RootAccess.setEnabled(f.c,false);RootAccess.setEnabled(f.c,true);check(!generation.equals(RootAccess.policy(f.c).getString("generation")),"root policy generation reused");reports.put("root_policy_atomic_generation");JSONObject s=RootAccess.status(f.c);check(!s.optBoolean("available")&&!"granted".equals(s.optString("state")),"su presence treated as grant");reports.put("root_presence_is_not_authorization");}
        try(Fixture f=new Fixture(c,"uid")){f.start("echo forbidden > must-not-exist",0,System.currentTimeMillis()/1000+10);f.finished();check(f.process.exitValue()==126&&!new File(f.root,"must-not-exist").exists()&&!f.identity.exists(),"nonroot fallback executed user command");reports.put("nonroot_uid_guard_before_user_command");}
        try(Fixture f=new Fixture(c,"success")){f.start("printf 'quoted\\047value'; echo err-value >&2",android.os.Process.myUid(),System.currentTimeMillis()/1000+10);f.finished();check(read(f.exit).trim().equals("0")&&read(f.identity).trim().endsWith(" "+android.os.Process.myUid()),"ordinary UID supervisor exit receipt");check(new String(readStream(f.process.getInputStream()),StandardCharsets.UTF_8).equals("quoted'value"),"supervisor quoting/stdout");check(new String(readStream(f.process.getErrorStream()),StandardCharsets.UTF_8).contains("err-value"),"supervisor stderr");reports.put("ordinary_uid_watchdog_quoting_output_exit");}
        try(Fixture f=new Fixture(c,"exit")){f.start("exit 7",android.os.Process.myUid(),System.currentTimeMillis()/1000+10);f.finished();check(read(f.exit).trim().equals("7"),"supervisor hid command failure");reports.put("ordinary_uid_watchdog_nonzero_exit");}
        for(int action=0;action<3;action++)try(Fixture f=new Fixture(c,"revoke"+action)){f.start("sleep 10; echo forbidden > must-not-exist",android.os.Process.myUid(),System.currentTimeMillis()/1000+20);f.identity();if(action==0)f.lease.delete();else{RootAccess.setEnabled(f.c,false);if(action==2)RootAccess.setEnabled(f.c,true);}f.finished();check(read(f.reason).equals("revoked")&&!f.exit.exists()&&!new File(f.root,"must-not-exist").exists(),"supervisor ignored lease/policy revocation");reports.put(action==0?"ordinary_uid_watchdog_lease_cancel":action==1?"ordinary_uid_watchdog_switch_off":"ordinary_uid_watchdog_old_generation_cannot_resume");}
        try(Fixture f=new Fixture(c,"timeout")){f.start("sleep 10; echo forbidden > must-not-exist",android.os.Process.myUid(),System.currentTimeMillis()/1000+1);f.finished();check(read(f.reason).equals("timeout")&&!f.exit.exists(),"supervisor timeout failed");reports.put("ordinary_uid_watchdog_timeout");}
        TaskController controller=TaskController.get(c);JSONObject t=controller.begin("c:"+suite+"-root","human-root-checks","验证Root开关和真实身份"),sc=a("conversation",t.getString("conversation"),"task_id",t.getString("id"),"call_id","root-tests");WorkbenchClient w=WorkbenchClient.get(c);boolean original=RootAccess.enabled(c);
        try {
            // This new setting must start off; never request a real su grant as an automated test.
            check(!original,"root switch unexpectedly enabled before opt-in");
            boolean rejected=false;try{new LocalToolKernel(c).call("terminal_start",a("command","echo forbidden > root-forbidden.txt").put("root",true),sc);}catch(SecurityException expected){rejected=true;}check(rejected,"kernel root switch bypass");JSONObject direct=w.call("terminal_start",a("command","id -u").put("root",true),sc);check(!direct.optBoolean("ok")&&direct.optString("error").contains("disabled"),"worker root switch bypass");reports.put("kernel_and_worker_root_off_gate");
            JSONObject job=w.call("terminal_start",a("command","id -u"),sc);for(int i=0;i<70&&job.optLong("finished_at")==0;i++){Thread.sleep(40);job=w.call("terminal_status",a("job_id",job.getString("job_id")),sc);}check(job.getInt("exit_code")==0&&!job.optBoolean("root_requested")&&!job.optBoolean("root_verified")&&job.getInt("effective_uid")==android.os.Process.myUid(),"ordinary job falsely root");reports.put("ordinary_terminal_identity_is_not_root");
            JSONObject task=new JSONObject(t.toString()).put("criteria",new JSONArray().put(a("kind","terminal_job","job_id",job.getString("job_id")).put("root",true)));check(!TaskVerifier.verify(c,task).optBoolean("verified"),"ordinary job passed root criterion");rejected=false;try{TaskVerifier.validate(new JSONArray().put(a("kind","terminal_job","job_id",job.getString("job_id"))),"Run id -u as root");}catch(Exception expected){rejected=true;}check(rejected,"root goal accepted nonroot evidence");rejected=false;try{TaskVerifier.validate(new JSONArray().put(a("kind","terminal_job","job_id",job.getString("job_id"))),"用Root权限运行 id -u");}catch(Exception expected){rejected=true;}check(rejected,"Chinese root goal accepted nonroot evidence");reports.put("native_root_verifier_requires_uid_zero");
            if(RootAccess.executable()==null){RootAccess.setEnabled(c,true);JSONObject worker=w.call("workbench_status",a(),sc).getJSONObject("root");check(worker.optBoolean("enabled")&&!worker.optBoolean("available")&&!worker.optBoolean("su_found"),"worker cached stale root policy");check(!w.call("terminal_start",a("command","id -u").put("root",true),sc).optBoolean("ok"),"missing su silently fell back");check(!RootAccess.probe(c).optBoolean("available"),"missing su reported granted");RootAccess.setEnabled(c,false);check(!w.call("workbench_status",a(),sc).getJSONObject("root").optBoolean("enabled"),"worker did not see switch off");reports.put("real_missing_su_and_cross_process_policy");}else reports.put("su_detected_real_grant_not_requested_by_tests");
            JSONArray tools=new LocalToolKernel(c).mcpTools();check(tools.length()==74,"tool discovery count");boolean schema=false;for(int i=0;i<tools.length();i++)if(tools.getJSONObject(i).getString("name").equals("terminal_start"))schema=tools.getJSONObject(i).getJSONObject("inputSchema").getJSONObject("properties").has("root");check(schema,"root job option absent from schema");reports.put("root_tool_discovery_and_schema");
        }finally{if(RootAccess.enabled(c)!=original)RootAccess.setEnabled(c,original);controller.finish(sc,a("outcome","cancelled","reason","Controlled Root capability checks ended; no real root grant or privileged command was executed."));}
        return reports;
    }
    static byte[] readStream(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}
}
